contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address attacker, uint value, bytes memory data) public payable {
        require(attacker != address(this), "attacker must not be the test contract");
        require(attacker != c.owner(), "attacker must not be the owner");
        require(address(this).balance >= value, "not enough balance");

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool withdrawReverted;
        try c.withdraw(value) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney{value: value}(attacker, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        assert(withdrawReverted && withdrawAllReverted && sendMoneyReverted && c.depositsCount() == beforeDeposits && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

