contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, address target, uint outValue, bytes memory data) public payable {
        require(amount > 0 && amount <= address(this).balance);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Setup: send ether via the payable fallback; must succeed for non-owner msg.sender.
        (bool fallbackOk, ) = address(c).call{value: amount}("");
        require(fallbackOk);

        uint afterFallbackBalance = address(c).balance;
        uint afterFallbackDeposits = c.depositsCount();

        // Non-owner msg.sender (this test contract) calls owner-only functions.
        bool withdrawReverted;
        try c.withdraw(outValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, outValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        assert(
            afterFallbackBalance == beforeBalance + amount &&
            afterFallbackDeposits == beforeDeposits + 1 &&
            withdrawReverted &&
            withdrawAllReverted &&
            sendMoneyReverted &&
            address(c).balance == afterFallbackBalance &&
            c.depositsCount() == afterFallbackDeposits
        );
    }

    receive() external payable {}
}

