    constructor(C _c) { c = _c; }

    function run(uint amount, uint wamount) public payable {
        require(amount <= address(this).balance);
        require(wamount <= address(c).balance);

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool fbReverted;
        try c.fallback{value: amount}() { fbReverted = false; } catch { fbReverted = true; }

        bool wReverted;
