        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        assert(fbReverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance
            || !fbReverted && afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount);
        assert(wReverted && afterBalance >= wamount
            || !wReverted && afterBalance == beforeBalance + amount - wamount);
    }

    receive() external payable {}
}

